请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-008

=== 用户原始指令 (query.txt) ===
帮我弄几个口味勾选点开能加到日历看到拼单完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄几个口味勾选点开能加到日历看到拼单完成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "group_buy_done_001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "groupBuy": {
      "title": {
        "type": "string",
        "description": "拼单团购口味选择卡片标题",
        "sampleValue": "拼单口味"
      },
      "statusText": {
        "type": "string",
        "description": "拼单当前确认状态",
        "sampleValue": "完成"
      },
      "flavorOneName": {
        "type": "string",
        "description": "第一个可勾选口味名称",
        "sampleValue": "草莓"
      },
      "flavorOneSelected": {
        "type": "boolean",
        "description": "第一个口味是否已勾选",
        "sampleValue": true
      },
      "flavorTwoName": {
        "type": "string",
        "description": "第二个可勾选口味名称",
        "sampleValue": "芒果"
      },
      "flavorTwoSelected": {
        "type": "boolean",
        "description": "第二个口味是否已勾选",
        "sampleValue": true
      },
      "calendarEntityId": {
        "type": "string",
        "description": "用于打开拼单完成日历事件的日程唯一标识",
        "sampleValue": "group_buy_done_001"
      },
      "actionLabel": {
        "type": "string",
        "description": "查看拼单完成日程的动作文案",
        "sampleValue": "查看日历"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/checkmark_calendar_fill.svg",
      "description": "带对勾的日历本地 SVG 图标，适合表达拼单完成后查看日程确认。"
    }
  ]
}

